import { describe, it, expect, vi } from "vitest";
import { randomUUID } from "node:crypto";
vi.mock("@/lib/db", () => ({ db: {} }));
import {
  decodeCursor,
  encodeCursor,
  userFilters,
  overrideInput,
} from "@/lib/admin/contracts";
import { countAdminUsage } from "@/lib/admin/usage";
import { adminUserSelect } from "@/lib/admin/projections";
describe("operator contracts and accounting", () => {
  it("bounds filters and strictly validates cursors and patches", () => {
    expect(userFilters.safeParse({ search: "x".repeat(161) }).success).toBe(
      false,
    );
    expect(userFilters.safeParse({ token: "x" }).success).toBe(false);
    const row = {
      id: randomUUID(),
      createdAt: new Date("2026-10-20T00:00:00.000Z"),
    };
    expect(decodeCursor(encodeCursor(row))).toEqual(row);
    for (const c of [
      "invalid",
      Buffer.from('["bad","bad"]').toString("base64url"),
    ])
      expect(() => decodeCursor(c)).toThrow("INVALID_INPUT");
    expect(
      overrideInput.safeParse({
        targetId: row.id,
        plan: "PAID",
        startsAt: null,
        expiresAt: null,
        reasonCode: "Free text",
        requestId: randomUUID(),
        confirmation: false,
      }).success,
    ).toBe(false);
  });
  it("excludes credentials, subjects, resume paths and content from projections", () => {
    for (const key of [
      "googleId",
      "encryptedRefreshToken",
      "currentAttachmentId",
      "gmailScopes",
      "planOverrideReason",
      "suspensionReason",
    ])
      expect(adminUserSelect).not.toHaveProperty(key);
  });
  it("deduplicates imports, counts uncertain attempts, direct assignments and overlaps", () => {
    const period = {
      id: "month",
      kind: "MONTHLY" as const,
      startsAt: new Date("2026-10-01Z"),
      operationalEndsAt: new Date("2026-11-01Z"),
    };
    const base = {
      userId: "owner",
      dailyPeriodId: "day",
      monthlyPeriodId: "month",
      chargedAt: new Date("2026-10-20Z"),
    };
    const rs = [
      { ...base, deliveryKey: "a", status: "CONFIRMED" as const },
      {
        ...base,
        deliveryKey: "b",
        monthlyPeriodId: "old",
        status: "UNCERTAIN" as const,
      },
      {
        ...base,
        deliveryKey: "c",
        status: "RESERVED" as const,
        chargedAt: null,
      },
      { ...base, deliveryKey: "d", status: "RELEASED" as const },
    ];
    const es = [
      { userId: "owner", deliveryKey: "a", chargedAt: base.chargedAt },
      { userId: "owner", deliveryKey: "e", chargedAt: base.chargedAt },
    ];
    expect(countAdminUsage(period, rs, es)).toEqual({
      sent: 2,
      reserved: 2,
      importedSent: 1,
      importedReserved: 1,
    });
  });
});
